// Extract candidate rejection data
const data = $input.all()[0].body;

return [
  {
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    position: data.position || 'Software Engineer',
    rejectionReason: data.rejectionReason || 'We appreciate your interest and effort in applying',
    feedbackSummary: data.feedbackSummary || 'After careful consideration, we have decided to move forward with other candidates',
    hrEmail: data.hrEmail || 'hr@company.com',
    allowReapply: data.allowReapply !== false,
    reapplyAfterMonths: data.reapplyAfterMonths || 6
  }
]
